INSERT INTO public.cms_texts (key, page, section, he_text, en_text, is_rich) VALUES
  ('gamesHub.benefits.0.body', 'games-hub', 'benefits', 'השאלות הנכונות מחזירות את ההתרגשות הראשונית. בלי לדבר על זה. בלי תרגילים.', 'The right questions bring back that early thrill. Without talking about it. Without ''exercises.''', false),
  ('gamesHub.benefits.0.title', 'games-hub', 'benefits', 'תשוקה', 'Passion', false),
  ('gamesHub.benefits.1.body', 'games-hub', 'benefits', 'תגלו על בני הזוג שלכם דברים שלא ידעתם - ועל החברים, דברים שלא חשבתם לשאול.', 'Discover things about your partner - and your friends - you''d never have thought to ask.', false),
  ('gamesHub.benefits.1.title', 'games-hub', 'benefits', 'חברות', 'Friendship', false),
  ('gamesHub.benefits.2.body', 'games-hub', 'benefits', 'הנאה אמיתית, בלי תירוצים. ערב שמתחיל בקליק והופך למשחק שלא רוצים לסיים.', 'Real enjoyment, no excuses. An evening that starts with a click and turns into a game you don''t want to end.', false),
  ('gamesHub.benefits.2.title', 'games-hub', 'benefits', 'כיף', 'Fun', false),
  ('gamesHub.breadcrumbGames', 'games-hub', 'breadcrumbgames', 'משחקים', 'Games', false),
  ('gamesHub.breadcrumbHome', 'games-hub', 'breadcrumbhome', 'בית', 'Home', false),
  ('gamesHub.catalogueHint', 'games-hub', 'cataloguehint', 'בחרו משחק, פתחו על הטלפון, ומתחילים. בלי הורדות, בלי הכנות.', 'Pick one, open it on your phone, and start. No downloads, no prep.', false),
  ('gamesHub.cataloguePill', 'games-hub', 'cataloguepill', 'הקטלוג', 'Catalogue', false),
  ('gamesHub.catalogueTitle', 'games-hub', 'cataloguetitle', 'מה משחקים הלילה?', 'What are we playing tonight?', false),
  ('gamesHub.heroSparkleChip', 'games-hub', 'herosparklechip', 'זוגי · בחינם', '2-player · free', false),
  ('gamesHub.newBadge', 'games-hub', 'newbadge', 'חדש 🔥', 'New 🔥', false),
  ('gamesHub.noActiveGames', 'games-hub', 'noactivegames', 'עדיין אין משחקים פעילים.', 'No active games yet.', false),
  ('gamesHub.personas.0.body', 'games-hub', 'personas', 'אתם רוצים לדעת הכל - אבל "מה הכי הפחיד אותך כילד?" לא נשאלת בקפה השני. אנחנו שואלים את זה בשבילכם, באופן שצוחק על הרצינות.', 'You want to know everything - but "what scared you most as a kid?" doesn''t fly on date two. We ask it for you - in a way that laughs at the seriousness of it.', false),
  ('gamesHub.personas.0.quote', 'games-hub', 'personas', '״להכיר מישהו לעומק לא דורש שנים. רק את השאלה הנכונה.״', '“Knowing someone deeply doesn’t take years. Just the right question.”', false),
  ('gamesHub.personas.0.tag', 'games-hub', 'personas', 'סקרנות', 'Curiosity', false),
  ('gamesHub.personas.0.title', 'games-hub', 'personas', 'הזוגות החדשים', 'The new couples', false),
  ('gamesHub.personas.1.body', 'games-hub', 'personas', 'אתם לא איבדתם את הזוגיות. רק את הזמן לזכור אותה. מיאושי דוחס בחצי שעה את מה שמסעדה רומנטית עושה בשלוש.', 'You haven''t lost the relationship. Only the time to remember it. Mioshy compresses into thirty minutes what a romantic dinner does in three hours.', false),
  ('gamesHub.personas.1.quote', 'games-hub', 'personas', '״חצי שעה במקום הנכון - זה לא מעט. זה הכל.״', '“Thirty minutes in the right place - isn’t a little. It’s everything.”', false),
  ('gamesHub.personas.1.tag', 'games-hub', 'personas', 'תזכורת', 'Reminder', false),
  ('gamesHub.personas.1.title', 'games-hub', 'personas', 'הזוגות באמצע', 'Couples in the middle', false),
  ('gamesHub.personas.2.body', 'games-hub', 'personas', 'אתם מסיימים אחד לשני את המשפטים. עכשיו רק צריך משפטים חדשים להתחיל. אנחנו לא נספר לכם משהו שלא ידעתם - רק נשאל את השאלה שלא חשבתם לשאול.', 'You finish each other''s sentences. Now you just need new sentences to start. We won''t tell you something you didn''t know - we''ll just ask the question you didn''t think to ask.', false),
  ('gamesHub.personas.2.quote', 'games-hub', 'personas', '״מי שחושב שהוא יודע הכל - שואל את השאלות הלא נכונות.״', '“Anyone who thinks they know it all - is asking the wrong questions.”', false),
  ('gamesHub.personas.2.tag', 'games-hub', 'personas', 'הפתעה', 'Surprise', false),
  ('gamesHub.personas.2.title', 'games-hub', 'personas', 'הזוגות הוותיקים', 'The veterans', false),
  ('gamesHub.personasHeader.eyebrow', 'games-hub', 'personasheader', 'למי', 'For whom', false),
  ('gamesHub.personasHeader.lede', 'games-hub', 'personasheader', 'בכל שלב בזוגיות מחכות שאלות. אנחנו רק יודעים מתי לשאול אותן.', 'Every stage of a relationship has its waiting questions. We just know when to ask them.', false),
  ('gamesHub.personasHeader.titleLine1', 'games-hub', 'personasheader', 'אין זוגיות משעממת.', 'There are no boring couples.', false),
  ('gamesHub.personasHeader.titleLine2', 'games-hub', 'personasheader', 'רק שאלות שלא נשאלו.', 'Only questions never asked.', false),
  ('gamesHub.playArrow', 'games-hub', 'playarrow', 'שחקו עכשיו ←', 'Play the game →', false),
  ('gamesHub.playNow', 'games-hub', 'playnow', 'שחקו עכשיו', 'Play now', false),
  ('gamesHub.snakesDesc', 'games-hub', 'snakesdesc', 'לוח קלאסי עם שאלות ואתגרים זוגיים - שחקו על מכשיר אחד או על שני מכשירים שונים.', 'Classic board with couples questions & challenges - play on one device or remotely.', false),
  ('gamesHub.snakesName', 'games-hub', 'snakesname', 'נחשים וסולמות', 'Snakes & Ladders', false),
  ('gamesHub.snakesPlayers', 'games-hub', 'snakesplayers', 'עד 8 שחקנים', 'Up to 8 players', false),
  ('gamesHub.whyItWorks.eyebrow', 'games-hub', 'whyitworks', 'למה זה עובד', 'Why it works', false),
  ('gamesHub.whyItWorks.lede', 'games-hub', 'whyitworks', 'לא טיפול. לא קורס. לא ''כלים לזוגיות''. משחק. אבל אחד שעובד.', 'Not therapy. Not a course. Not ''tools for relationships.'' A game - but one that works.', false),
  ('gamesHub.whyItWorks.titleLine1', 'games-hub', 'whyitworks', 'שאלה אחת.', 'One question.', false),
  ('gamesSlug.gameNotFoundBody', 'games-slug', 'gamenotfoundbody', 'המשחק הזה לא זמין כרגע.', 'This game is not available right now.', false),
  ('gamesSlug.gameNotFoundTitle', 'games-slug', 'gamenotfoundtitle', 'המשחק לא נמצא', 'Game not found', false),
  ('gamesSlug.missingWheelBody', 'games-slug', 'missingwheelbody', 'נסו שוב מאוחר יותר.', 'Please try again later.', false),
  ('gamesSlug.missingWheelTitle', 'games-slug', 'missingwheeltitle', 'חסר גלגל למשחק', 'Game is missing a wheel', false),
  ('gamesSlug.tutorial.badge', 'games-slug', 'tutorial', 'ברוכים הבאים', 'Welcome', false),
  ('gamesSlug.tutorial.cta', 'games-slug', 'tutorial', 'מעולה, יוצאים לדרך', 'Got it, let''s start', false),
  ('gamesSlug.tutorial.dismiss', 'games-slug', 'tutorial', 'סגירה', 'Close', false),
  ('gamesSlug.tutorial.step1', 'games-slug', 'tutorial', 'סובבו את הגלגל', 'Spin the wheel', false),
  ('gamesSlug.tutorial.step2', 'games-slug', 'tutorial', 'קבלו שאלה - אמת או חובה', 'Reveal a Truth or Dare', false),
  ('gamesSlug.tutorial.step3', 'games-slug', 'tutorial', 'ענו או בצעו, ועברו לסיבוב הבא', 'Answer or do it — then spin again', false),
  ('gamesSlug.tutorial.title', 'games-slug', 'tutorial', 'ככה זה עובד', 'Here''s how it works', false),
  ('home.headline', 'home', 'headline', 'התקרבו. צחקו. התחברו.', 'Get closer. Laugh harder. Connect deeper.', false),
  ('homeV2.adultGames.cta', 'homepage', 'adultgames', 'אל הסקס של מיאושי', 'Enter Mioshy''s Sex', false),
  ('homeV2.adultGames.eyebrow', 'homepage', 'adultgames', '- חוקי הסקס של מיאושי -', '- Mioshy''s Sex Rules -', false),
  ('homeV2.adultGames.headline', 'homepage', 'adultgames', 'לא לכל אחד.<br></br><em>לאמיצים בלבד.</em>', 'Not for everyone.<br></br><em>For the brave only.</em>', true),
  ('homeV2.adultGames.lead', 'homepage', 'adultgames', 'המומחים של מיאושי הכינו עבורכם את "הסקס של מיאושי" - משחקי מין לזוגות שמחפשים לגוון, להפתיע ולהחזיר את הריגוש. <strong>חוויה שתישאר אתכם הרבה אחרי שהאורות יכבו.</strong>', 'Mioshy''s experts built "Mioshy''s Sex" for couples who want to mix things up, surprise each other, and bring the thrill back. <strong>An experience that stays with you long after the lights go out.</strong>', true),
  ('homeV2.adultGames.pill1', 'homepage', 'adultgames', '18+', '18+', false),
  ('homeV2.adultGames.pill2', 'homepage', 'adultgames', 'הסקס של מיאושי', 'Mioshy''s Sex', false),
  ('homeV2.adultGames.pill3', 'homepage', 'adultgames', 'פרטיות מוחלטת', 'Total privacy', false),
  ('homeV2.adultGames.pillar1Body', 'homepage', 'adultgames', 'סקסולוגים בכירים, מטפלים זוגיים מהאקדמיה, וחוקרי אינטימיות.', 'Senior sexologists, academic couples therapists, and intimacy researchers.', false),
  ('homeV2.adultGames.pillar1Title', 'homepage', 'adultgames', 'נכתב על־ידי מומחים', 'Written by experts', false),
  ('homeV2.adultGames.pillar2Body', 'homepage', 'adultgames', 'כל מהלך במשחק נבנה עם ציפייה - מובל בקצב שלכם, אל בילוי וסקס שתזכרו הרבה אחרי שהמשחק נגמר.', 'Every move in the game builds with anticipation — paced for you, leading to a night and sex you''ll remember long after the game ends.', false),
  ('homeV2.adultGames.pillar2Title', 'homepage', 'adultgames', 'עוצב לחדר המיטות', 'Designed for the bedroom', false),
  ('homeV2.adultGames.pillar3Body', 'homepage', 'adultgames', 'זמין מתי שתרצו - תקבעו ערב, תפתחו את המשחק, וההוראות מוכנות לכם. <strong>רכישה אחת, גישה מלאה - לכל החיים.</strong>', 'Available whenever you want — pick an evening, open the game, and there''s a couple-ready experience waiting. <strong>One purchase, full access — for life.</strong>', true),
  ('homeV2.adultGames.pillar3Title', 'homepage', 'adultgames', 'רק לכם. בכל רגע.', 'Just yours. Anytime.', false),
  ('homeV2.authority.eyebrow', 'homepage', 'authority', 'הניצוץ חוזר בהחלטה!', 'The spark returns with a decision!', false),
  ('homeV2.authority.headlinePart1', 'homepage', 'authority', '5 שנים. 500+ זוגות.', '5 years. 500+ couples.', false),
  ('homeV2.authority.improvementLabel', 'homepage', 'authority', 'מדווחים על שיפור', 'Report improvement', false),
  ('homeV2.authority.narrative', 'homepage', 'authority', 'מאז 2021 אנחנו מלווים זוגות. <strong>שמענו אלפי סיפורים</strong> - ראינו זוגות צוחקים, בוכים, מתפייסים, חוזרים אחד אל השנייה. כל מה שאנחנו עושים - נולד מהם. מהשיחות, מהמשובים, מהדמעות, מהחיוכים. זאת הסיבה שמיאושי לא נשאר אותו דבר. הוא משתנה, גדל, מתחדש. <strong>בדיוק כמו זוגיות בריאה.</strong>', 'Since 2021 we''ve been working with couples. <strong>We''ve heard thousands of stories</strong> - couples laughing, crying, making up, finding their way back to each other. Everything we do was born from them. From the conversations, the feedback, the tears, the smiles. That''s why Mioshy doesn''t stay the same. It changes, grows, evolves. <strong>Just like a healthy relationship.</strong>', true),
  ('homeV2.authority.ratingLabel', 'homepage', 'authority', 'דירוג ממוצע', 'Average rating', false),
  ('homeV2.authority.since', 'homepage', 'authority', 'מאז 2021', 'Since 2021', false),
  ('homeV2.authority.sinceLabel', 'homepage', 'authority', 'בישראל וברחבי העולם', 'In Israel and around the world', false),
  ('homeV2.authority.statCouplesLabel', 'homepage', 'authority', 'הזוגות שבחרו במיאושי', 'Couples who chose Mioshy', false),
  ('homeV2.couplesGames.callout', 'homepage', 'couplesgames', '"תכניסו תשוקה. תתחברו מחדש. תתאהבו ותחזירו את הפרפרים - במיוחד למי שבזוגיות ארוכה עם ילדים, ומרגיש איך השחיקה עושה את שלה."', '"Bring in desire. Reconnect. Fall in love again and bring back the butterflies - especially if you''re in a long relationship with kids and feel the burnout doing its thing."', false),
  ('homeV2.couplesGames.calloutName', 'homepage', 'couplesgames', 'ענת', 'Sarah', false),
  ('homeV2.couplesGames.card1Tag', 'homepage', 'couplesgames', 'מסקרן', 'Curious', false),
  ('homeV2.couplesGames.card2Tag', 'homepage', 'couplesgames', 'מעמיק', 'Deep', false),
  ('homeV2.couplesGames.card3Tag', 'homepage', 'couplesgames', 'קליל', 'Light', false),
  ('homeV2.couplesGames.ctaPrimary', 'homepage', 'couplesgames', 'לכל המשחקים', 'See all games', false),
  ('homeV2.couplesGames.eyebrow', 'homepage', 'couplesgames', 'המשחקים של מיאושי', 'Mioshy''s games', false),
  ('homeV2.couplesGames.headlinePart1', 'homepage', 'couplesgames', 'המשחקים שכבר', 'The games that already', false),
  ('homeV2.couplesGames.lead', 'homepage', 'couplesgames', 'רוצים להיפתח? להתחבר? להתגלות מחדש? 500+ זוגות בישראל כבר ממליצים - מהסלון, מהמיטה, ואפילו כשאחד מכם בחו"ל. אתם הבאים בתור.', 'Want to open up? Connect? Discover each other again? Thousands of couples in Israel are already recommending - from the couch, from the bed, even when one of you is overseas. You''re up next.', false),
  ('homeV2.education.body', 'homepage', 'education', 'שגרה, ילדים, קריירה, עייפות - הם לא רעים. הם פשוט <strong>דוחקים את הזוגיות לפינה</strong>. וביום שבו אתם מבינים שאתם זרים, השחיקה כבר נעשתה לפני שנים.', 'Routine, kids, career, fatigue - they''re not bad. They just <strong>push the relationship into a corner</strong>. And the day you realize you''ve become strangers, the erosion happened years ago.', true),
  ('homeV2.education.eyebrow', 'homepage', 'education', 'למה זה קורה', 'Why this happens', false),
  ('homeV2.education.headline', 'homepage', 'education', 'זוגיות לא נשברת בלילה אחד.<br></br>היא נשחקת לאט.', 'Relationships don''t break in one night.<br></br>They erode slowly.', true),
  ('homeV2.finalCta.choice1Body', 'homepage', 'finalcta', 'לשבור את הקרח, להנות מערב מהנה יחד. שאלות, אתגרים ומשחקים שיוצרים שיחה אמיתית - מהסלון, בלי הכנה.', 'Break the ice, enjoy a fun night together. Questions, challenges, and games that spark a real conversation - from the couch, no prep needed.', false),
  ('homeV2.finalCta.choice1Cta', 'homepage', 'finalcta', 'התחילו עכשיו', 'Start now', false),
  ('homeV2.finalCta.choice1Tag', 'homepage', 'finalcta', 'הכי פופולרי', 'Most popular', false),
  ('homeV2.finalCta.choice1Title', 'homepage', 'finalcta', 'משחקי זוגיות אונליין', 'Online couples games', false),
  ('homeV2.finalCta.choice2Body', 'homepage', 'finalcta', 'למי שמוכן ואוהב לשבור את השגרה - גם בסקס. משחקים נועזים שעיצבנו עבור הזוגות הכי הרפתקניים שלנו.', 'For those ready and willing to break the routine - in bed too. Bold games we designed for our most adventurous couples.', false),
  ('homeV2.finalCta.choice2Cta', 'homepage', 'finalcta', 'גלו את המשחקים', 'Explore the games', false),
  ('homeV2.finalCta.choice2Tag', 'homepage', 'finalcta', 'הסקס של מיאושי', 'Mioshy''s Sex', false),
  ('homeV2.finalCta.choice2Title', 'homepage', 'finalcta', 'הסקס של מיאושי', 'Mioshy''s Sex', false),
  ('homeV2.finalCta.description', 'homepage', 'finalcta', 'מצטרפים ל-500+ זוגות שכבר עשו את הצעד הראשון. בחרו איך להתחיל:', 'Joining thousands of couples who''ve already taken the first step. Choose how to begin:', false),
  ('homeV2.finalCta.eyebrow', 'homepage', 'finalcta', 'הצעד הראשון', 'The first step', false),
  ('homeV2.finalCta.headline', 'homepage', 'finalcta', 'תרגישו קרובים שוב.<br></br>זה מתחיל הערב.', 'Feel close again.<br></br>It starts tonight.', true),
  ('homeV2.finalCta.trust1', 'homepage', 'finalcta', 'ללא מחויבות', 'No commitment', false),
  ('homeV2.finalCta.trust2', 'homepage', 'finalcta', 'פרטיות מלאה', 'Full privacy', false),
  ('homeV2.finalCta.trust3', 'homepage', 'finalcta', '100% הנאה', '100% pleasure', false),
  ('homeV2.forWhom.cta', 'homepage', 'forwhom', 'בואו לגלות מה קורה בזוגיות שלכם', 'Find out what''s going on in your relationship', false),
  ('homeV2.forWhom.ctaBig', 'homepage', 'forwhom', 'בואו גלו על הזוגיות שלכם דברים שלא ידעתם - חינם לגמרי.', 'Discover things about your relationship you never knew - completely free.', false),
  ('homeV2.forWhom.ctaSmall', 'homepage', 'forwhom', 'בחינם · 90 שניות · בלי הרשמה', 'Free · 90 seconds · No signup', false),
  ('homeV2.forWhom.description', 'homepage', 'forwhom', 'הליווי של מיאושי לא לכולם. הוא למי שמוכן לבחור בזוגיות אחרת.', 'Mioshy''s coaching isn''t for everyone. It''s for couples ready to choose a different kind of relationship.', false),
  ('homeV2.forWhom.eyebrow', 'homepage', 'forwhom', 'למי זה מתאים', 'Who it''s for', false),
  ('homeV2.forWhom.headlinePart1', 'homepage', 'forwhom', 'אם אתם מזהים את עצמכם', 'If you recognize yourself', false),
  ('homeV2.forWhom.headlinePart2', 'homepage', 'forwhom', 'באחד מאלה - מיאושי ', 'in one of these - Mioshy is ', false),
  ('homeV2.forWhom.persona1Desc', 'homepage', 'forwhom', 'השגרה השתלטה ואתם מתגעגעים למבטים של פעם, לרצון להיות יחד, לחיוך הספונטני.', 'Routine took over and you miss the looks, the wanting to be together, the spontaneous smile.', false),
  ('homeV2.forWhom.persona1Link', 'homepage', 'forwhom', 'המסע הזוגי המודרך', 'The guided couples journey', false),
  ('homeV2.forWhom.persona1Title', 'homepage', 'forwhom', 'רוצים להחזיר את הניצוץ', 'You want the spark back', false),
  ('homeV2.forWhom.persona2Desc', 'homepage', 'forwhom', 'הילדים, העבודה, הבית - והזוגיות נשארה אחרונה. אתם רוצים להחזיר אותה לראש הסדר.', 'Kids, work, the house - and the relationship ended up last. You want it back at the top.', false),
  ('homeV2.forWhom.persona2Link', 'homepage', 'forwhom', 'ליווי חודשי גמיש', 'Flexible monthly coaching', false),
  ('homeV2.forWhom.persona2Title', 'homepage', 'forwhom', 'רוצים זמן זוגי באמת', 'You want real couple time', false),
  ('homeV2.forWhom.persona3Desc', 'homepage', 'forwhom', 'הייתם אצל מטפלת. עזר באופן חלקי. אתם מחפשים משהו אחר - חוויתי, פחות כבד, יותר ביחד.', 'You''ve been to a therapist. It helped, partly. You''re looking for something different - experiential, lighter, more together.', false),
  ('homeV2.forWhom.persona3Link', 'homepage', 'forwhom', 'ליווי עם המומחים שלנו', 'Coaching with our experts', false),
  ('homeV2.forWhom.persona3Title', 'homepage', 'forwhom', 'מחפשים מומחה שיעזור', 'You''re looking for an expert', false),
  ('homeV2.forWhom.persona4Desc', 'homepage', 'forwhom', 'הקשר טוב. אתם רק רוצים להעלות הילוך - חוויות חדשות, שיחות חדשות, אינטימיות חדשה.', 'The relationship is good. You just want to take it up a notch - new experiences, new conversations, new intimacy.', false),
  ('homeV2.forWhom.persona4Link', 'homepage', 'forwhom', 'משחקי חיבור ותקשורת', 'Connection and communication games', false),
  ('homeV2.forWhom.persona4Title', 'homepage', 'forwhom', 'רוצים להתחבר מחדש', 'You want to reconnect', false),
