  ('journeyAssessment.interstitial.continue', 'journey-assessment', 'interstitial', 'ממשיכים', 'Continue', false),
  ('journeyAssessment.interstitial.step1.body', 'journey-assessment', 'interstitial', 'עוד רגע ונשאל איך אתם מתמודדים ברגעים הקשים יותר יחד. תיקחו נשימה.', 'In a moment we''ll ask about the harder moments. Take a breath.', false),
  ('journeyAssessment.interstitial.step1.title', 'journey-assessment', 'interstitial', 'סיימתם את הבלוק הראשון', 'First block done', false),
  ('journeyAssessment.interstitial.step2.body', 'journey-assessment', 'interstitial', 'אינטימיות וחיבור רגשי. בלי שיפוט, בלי תשובות נכונות. עוד שניים-שלושה בלוקים.', 'Intimacy and emotional connection. No judgment, no right answers. Two or three blocks left.', false),
  ('journeyAssessment.interstitial.step2.title', 'journey-assessment', 'interstitial', 'זה החלק האישי', 'This is the personal part', false),
  ('journeyAssessment.interstitial.step3.body', 'journey-assessment', 'interstitial', 'סיימתם. עכשיו ניגע בחיים היומיומיים שלכם — ואז בעדיפויות שלכם.', 'Done with that. Next we touch the everyday, then your priorities.', false),
  ('journeyAssessment.interstitial.step3.title', 'journey-assessment', 'interstitial', 'חברות זוגית — הבסיס של הכל', 'Friendship — the base of everything', false),
  ('journeyAssessment.interstitial.step4.body', 'journey-assessment', 'interstitial', 'השלב האחרון: לדרג את העדיפויות שלכם. זה מה שמכוון את כל המסלול הלאה.', 'Last step: ranking your priorities. This is what shapes the path going forward.', false),
  ('journeyAssessment.interstitial.step4.title', 'journey-assessment', 'interstitial', 'כמעט סיימתם', 'Almost there', false),
  ('journeyAssessment.interstitial.stepCounter', 'journey-assessment', 'interstitial', 'שלב {n} / 4', 'Step {n} / 4', false),
  ('journeyAssessment.intro.backLink', 'journey-assessment', 'intro', 'אולי אחר כך', 'Maybe later', false),
  ('journeyAssessment.intro.cta', 'journey-assessment', 'intro', 'אנחנו בפנים', 'We''re in', false),
  ('journeyAssessment.intro.ctaBusy', 'journey-assessment', 'intro', 'שומרים…', 'Saving…', false),
  ('journeyAssessment.intro.durationBody', 'journey-assessment', 'intro', 'האבחון לוקח כ-7 דקות. אחר כך — צעד קצר אחת לשבוע, בקצב שלכם.', 'The assessment takes about 7 minutes. After that — one short step a week, at your pace.', false),
  ('journeyAssessment.intro.durationTitle', 'journey-assessment', 'intro', '10 דקות בשבוע, ארבעה שבועות', '10 minutes a week, four weeks', false),
  ('journeyAssessment.intro.eyebrow', 'journey-assessment', 'intro', 'רגע לפני', 'Just before', false),
  ('journeyAssessment.intro.pactBody', 'journey-assessment', 'intro', '10 דקות לשבוע. בלי לחץ, בלי שיפוט. כשתרצו לוותר — תזכרו שהסכמתם להיות פה את הארבעה שבועות האלה.', '10 minutes a week. No pressure, no judgment. If you feel like quitting — remember you said you''d be here for these four.', false),
  ('journeyAssessment.intro.pactHeader', 'journey-assessment', 'intro', 'ארבעה שבועות, יחד', 'Four weeks, together', false),
  ('journeyAssessment.intro.privacyBody', 'journey-assessment', 'intro', 'כל אחד מכם עונה לבד. הצד השני לא רואה את התשובות האישיות שלכם, רק המומחה רואה.', 'Each of you answers alone. Your partner doesn''t see your personal answers — only the coach does.', false),
  ('journeyAssessment.intro.privacyTitle', 'journey-assessment', 'intro', 'התשובות שלכם — שלכם', 'Your answers — yours', false),
  ('journeyAssessment.intro.saveError', 'journey-assessment', 'intro', 'השמירה נכשלה — נסו שוב', 'Save failed — please retry', false),
  ('journeyAssessment.intro.subtitle', 'journey-assessment', 'intro', 'המסלול שלכם נבנה לפי התשובות. כדי שזה יעבוד צריך שתהיו בפנים.', 'Your path is built from your answers. For that to work, you have to be in.', false),
  ('journeyAssessment.intro.title', 'journey-assessment', 'intro', 'הסכם קטן ביניכם', 'A small agreement between you', false),
  ('journeyAssessment.paywallGate.body', 'journey-assessment', 'paywallgate', 'הצטרפו לשירות וקבלו ניתוח מעמיק, משימות שבועיות מותאמות, ושיחות עם מומחים.', 'Join the service and get an in-depth analysis, weekly personalized tasks, and expert consultations.', false),
  ('journeyAssessment.paywallGate.bullet1', 'journey-assessment', 'paywallgate', '2–4 משימות בשבוע שנבחרו ע"י מומחים - בדיוק למה שאתם צריכים', '2–4 expert-picked weekly tasks - matched precisely to your needs', false),
  ('journeyAssessment.paywallGate.bullet2', 'journey-assessment', 'paywallgate', 'שאלונים נוספים בשבועות הראשונים לכיוון מדויק יותר', 'Additional questionnaires in early weeks to sharpen your profile', false),
  ('journeyAssessment.paywallGate.bullet3', 'journey-assessment', 'paywallgate', 'שירות מותאם אישית לחלוטין - לא תוכנית גנרית', '100% personalized - not a generic program', false),
  ('journeyAssessment.paywallGate.bullet4', 'journey-assessment', 'paywallgate', 'שיחות עם מומחים כלולות במחיר - ללא תוספת', 'Expert consultations are included in the price - no add-ons', false),
  ('journeyAssessment.paywallGate.cancel', 'journey-assessment', 'paywallgate', 'אחר כך', 'Not now', false),
  ('journeyAssessment.paywallGate.cta', 'journey-assessment', 'paywallgate', 'הצטרפות לשירות', 'Join the service', false),
  ('journeyAssessment.paywallGate.loading', 'journey-assessment', 'paywallgate', 'מכין תשלום…', 'Preparing checkout…', false),
  ('journeyAssessment.paywallGate.price', 'journey-assessment', 'paywallgate', '₪98 / $33 לחודש - ניתן לביטול בכל עת', '$33 / ₪98 per month - cancel anytime', false),
  ('journeyAssessment.paywallGate.title', 'journey-assessment', 'paywallgate', 'תוכנית אישית - שבוע אחר שבוע', 'A personalized plan - week after week', false),
  ('journeyAssessment.priorityRanking.arrowsHint', 'journey-assessment', 'priorityranking', 'השתמשו בחצים לשינוי הסדר', 'Use the arrows to reorder', false),
  ('journeyAssessment.priorityRanking.moveDown', 'journey-assessment', 'priorityranking', 'הורד את {label}', 'Move {label} down', false),
  ('journeyAssessment.priorityRanking.moveUp', 'journey-assessment', 'priorityranking', 'העלה את {label}', 'Move {label} up', false),
  ('journeyAssessment.priorityRanking.position', 'journey-assessment', 'priorityranking', 'מקום {n}', 'Position {n}', false),
  ('journeyAssessment.question.continue', 'journey-assessment', 'question', 'המשך', 'Continue', false),
  ('journeyAssessment.question.reflectionPlaceholder', 'journey-assessment', 'question', 'לדוגמה: ארוחת ערב אחרי שהילדים נרדמו, שיחה במכונית, חיבוק רגיל ביום שלישי...', 'For example: dinner after the kids fell asleep, a chat in the car, an ordinary Tuesday hug...', false),
  ('journeyAssessment.question.saving', 'journey-assessment', 'question', 'שומר/ת…', 'Saving…', false),
  ('journeyAssessment.question.selectAnswer', 'journey-assessment', 'question', 'בחר/י תשובה כדי להמשיך', 'Select an answer to continue', false),
  ('journeyHub.activeAssignmentsBanner', 'journey-hub', 'activeassignmentsbanner', 'המסלול שלכם פעיל - המשיכו מאיפה שעצרתם', 'Your journey is active - pick up where you left off', false),
  ('journeyHub.breadcrumbHome', 'journey-hub', 'breadcrumbhome', 'בית', 'Home', false),
  ('journeyHub.breadcrumbJourney', 'journey-hub', 'breadcrumbjourney', 'ליווי עם מיאושי', 'Journey with Mioshy', false),
  ('journeyHub.ctaBlock.badge', 'journey-hub', 'ctablock', 'ללא כרטיס אשראי', 'No credit card', false),
  ('journeyHub.ctaBlock.sub', 'journey-hub', 'ctablock', '5 דקות, אבחון מקצועי, ותוכנית אישית מחכה לכם. אין התחייבות, אין כרטיס אשראי - רק כיוון.', '5 minutes, a professional diagnostic, and a personal plan waiting. No commitment, no credit card — just direction.', false),
  ('journeyHub.ctaBlock.title', 'journey-hub', 'ctablock', 'האבחון חינם. המסלול מתחיל כשתדעו שאתם בפנים.', 'The assessment is free. The journey starts when you''re in.', false),
  ('journeyHub.ctaSecondary', 'journey-hub', 'ctasecondary', 'איך זה עובד', 'How it works', false),
  ('journeyHub.faq.items.0.a', 'journey-hub', 'faq', 'אבחון אישי של 10 דקות, תוכנית עבודה שמתחדשת בכל חודש, גישה לכל המשחקים במיאושי (כולל הסקס של מיאושי), ומענה ישיר מהמומחים בצ''אט פנימי. הכל כלול במנוי השבועי — אין תוספות, אין הפתעות.', 'A 10-minute personal assessment, a work plan refreshed monthly, full access to every game on Mioshy (including Mioshy''s Sex), and direct chat with our experts. Everything''s included in the weekly subscription — no add-ons, no surprises.', false),
  ('journeyHub.faq.items.0.q', 'journey-hub', 'faq', 'מה אנחנו בעצם מקבלים בליווי?', 'What do we actually get with the coaching?', false),
  ('journeyHub.faq.items.1.a', 'journey-hub', 'faq', 'פסיכולוגים זוגיים, יועצי משפחה ומטפלי זוגות עם ניסיון של 10+ שנים. לכל זוג ממונה מומחה אישי שלומד אתכם לאורך הזמן ובונה לכם את התוכנית — לא צ''אט-בוט, לא תבנית.', 'Couples psychologists, family counselors, and couples therapists with 10+ years of experience. Each couple is paired with a personal expert who learns you over time and builds your plan — not a chatbot, not a template.', false),
  ('journeyHub.faq.items.1.q', 'journey-hub', 'faq', 'מי המומחים שעוקבים אחרינו?', 'Who are the experts following us?', false),
  ('journeyHub.faq.items.2.a', 'journey-hub', 'faq', 'ריחוק רגשי, תקשורת שעולה לוויכוח, חוסר אינטימיות, חיכוכים שחוזרים על עצמם, תחושה ש"איבדנו את עצמנו". אנחנו לא מבטיחים פתרון לכל דבר, אבל ב-90% מהזוגות יש שיפור משמעותי בתוך 6 שבועות.', 'Emotional distance, communication that escalates to fights, lack of intimacy, recurring friction, the feeling of "we lost ourselves". We don''t promise a fix for everything — but 90% of couples see meaningful improvement within 6 weeks.', false),
  ('journeyHub.faq.items.2.q', 'journey-hub', 'faq', 'איזה בעיות הליווי באמת פותר?', 'What problems does the coaching actually solve?', false),
  ('journeyHub.faq.items.3.a', 'journey-hub', 'faq', 'כשעה בשבוע בסך הכל — כפוף לזמן שלכם. תרגול קצר ביום-יומיים, שיחה אחת ארוכה בשבוע. הקצב שלכם, לא שלנו.', 'About an hour a week total — based on your bandwidth. A short practice every day or two, one longer conversation a week. Your pace, not ours.', false),
  ('journeyHub.faq.items.3.q', 'journey-hub', 'faq', 'כמה זמן זה דורש מאיתנו בשבוע?', 'How much time does it take per week?', false),
  ('journeyHub.faq.items.4.a', 'journey-hub', 'faq', 'כן. הנתונים מוצפנים. רק המומחה האישי שלכם רואה את התשובות. אנחנו לא מוכרים מידע, אין פרסומות, אין צד שלישי. החיוב מופיע תחת Mioshy בלבד.', 'Yes. Data is encrypted. Only your personal expert sees the answers. We don''t sell information, no ads, no third party. Billing shows only as Mioshy.', false),
  ('journeyHub.faq.items.4.q', 'journey-hub', 'faq', 'האם התשובות שלנו פרטיות?', 'Are our answers private?', false),
  ('journeyHub.faq.items.5.a', 'journey-hub', 'faq', 'בכל שלב, בקליק אחד. ללא חוזה, ללא קנסות. אחרי הביטול, לא תחויבו יותר — והגישה לתוכן שלכם נשארת עד סוף תקופת המנוי הנוכחית.', 'Anytime, one click. No contract, no penalties. After cancellation no further charges — and your content stays accessible until the end of the current billing period.', false),
  ('journeyHub.faq.items.5.q', 'journey-hub', 'faq', 'אפשר לעצור או לבטל בכל שלב?', 'Can we pause or cancel anytime?', false),
  ('journeyHub.faq.items.6.a', 'journey-hub', 'faq', 'תתחילו לבד. רוב הזוגות מתחילים כך — הצד השני מצטרף אחרי שבועיים-שלושה כשרואה שמשהו זז. אבחון מתחיל אצל אחד ומתקדם בקצב שלכם.', 'Start alone. Most couples start that way — the other partner joins within two-three weeks once they see something''s moving. The assessment can start with one person and build from there.', false),
  ('journeyHub.faq.items.6.q', 'journey-hub', 'faq', 'מה אם אחד מאיתנו לא מוכן/ה?', 'What if one of us isn''t ready?', false),
  ('journeyHub.faqSide.blurb', 'journey-hub', 'faqside', 'אספנו את השאלות שזוגות שואלים אותנו על האבחון, על המסלול ועל מה קורה אחרי. עדיין לא מצאתם תשובה?', 'We''ve gathered the most common questions about the assessment, the path, and what happens after. Didn''t find your answer?', false),
  ('journeyHub.faqSide.contactCta', 'journey-hub', 'faqside', 'דברו איתנו', 'Talk to us', false),
  ('journeyHub.faqSide.eyebrow', 'journey-hub', 'faqside', 'שאלות שזוגות שואלים', 'Questions couples ask', false),
  ('journeyHub.faqSide.titleLine1', 'journey-hub', 'faqside', 'יש לכם שאלות על המסע?', 'Have questions about the journey?', false),
  ('journeyHub.faqSide.titleLine2', 'journey-hub', 'faqside', 'יש לנו תשובות.', 'We have answers.', false),
  ('journeyHub.h1', 'journey-hub', 'h1', 'ליווי עם מיאושי', 'Journey with Mioshy', false),
  ('journeyHub.h1Sub', 'journey-hub', 'h1sub', 'מותאם אישית', 'personalised', false),
  ('journeyHub.how.badge', 'journey-hub', 'how', 'איך זה עובד', 'How it works', false),
  ('journeyHub.how.steps.0.body', 'journey-hub', 'how', 'אבחון קצר של תקשורת, אינטימיות, חיבור רגשי, חברות ומשפחה. בסוף תראו בדיוק איפה אתם עומדים - בלי ז''רגון, בלי מילוי מקום.', 'A short assessment of communication, intimacy, emotional connection, friendship, and family. By the end you''ll see exactly where you stand - no jargon, no filler.', false),
  ('journeyHub.how.steps.0.tag', 'journey-hub', 'how', 'האבחון', 'The diagnostic', false),
  ('journeyHub.how.steps.0.title', 'journey-hub', 'how', 'ממפים את הזוגיות ב-5 דקות', 'Map your relationship in 5 minutes', false),
  ('journeyHub.how.steps.1.body', 'journey-hub', 'how', 'תוצאות מיידיות: 3 נקודות החוזק שלכם, 2 נקודות החיכוך הגדולות ביותר, והדבר הראשון שהכי כדאי להתחיל לעבוד עליו - עכשיו.', 'Instant results: your 3 strongest areas, your 2 biggest friction points, and the one thing most worth working on first.', false),
  ('journeyHub.how.steps.1.tag', 'journey-hub', 'how', 'הניתוח', 'The analysis', false),
  ('journeyHub.how.steps.1.title', 'journey-hub', 'how', 'מקבלים אבחון אישי', 'Get your personal diagnostic', false),
  ('journeyHub.how.steps.2.body', 'journey-hub', 'how', 'המומחה ממיאושי לומד את הקשר שלכם, בונה תוכנית אישית, ועוקב אחריכם בצ''אט פנימי. תרגולים קצרים שמצטברים לכשעה בשבוע - בקצב שלכם.', 'Your Mioshy expert learns your relationship, builds a custom plan, and follows you in private chat. Short practices that add up to about an hour a week — at your pace.', false),
  ('journeyHub.how.steps.2.tag', 'journey-hub', 'how', 'המסלול', 'The path', false),
  ('journeyHub.how.steps.2.title', 'journey-hub', 'how', 'מומחה צמוד + תרגולים שבועיים', 'An expert + weekly practice', false),
  ('journeyHub.how.title', 'journey-hub', 'how', 'שלושה צעדים עד למסלול שלכם', 'Three steps to your plan', false),
  ('journeyHub.lede', 'journey-hub', 'lede', 'חלק מהשירותים שלנו מותאמים מראש לפי האבחון. מהרגע שהצטרפתם, המומחים שלנו עוקבים אחרי התשובות שלכם, שואלים אתכם שאלות נוספות, ובמהלך הזמן בונים עבורכם זוגיות חדשה. פסיכולוגים ויועצי זוגיות מטעמנו - אתם מקבלים את החבילה המלאה, והכל מכוון אליכם.', 'Some of our content is pre-tuned to your assessment. From the moment you sign up, our experts follow your answers, ask you new questions over time, and build a new relationship dynamic for you. Psychologists and couples counselors from our team — you get the full package, all of it tuned to you.', false),
  ('journeyHub.locked.backLink', 'journey-hub', 'locked', 'חזרה למיאושי שלי', 'Back to My Mioshy', false),
  ('journeyHub.locked.badge', 'journey-hub', 'locked', 'ליווי עם מיאושי', 'Journey with Mioshy', false),
  ('journeyHub.locked.h1Highlight', 'journey-hub', 'locked', 'נעול', 'locked', false),
  ('journeyHub.locked.h1Lead', 'journey-hub', 'locked', 'המסע', 'The journey is', false),
  ('journeyHub.locked.h1Tail', 'journey-hub', 'locked', '— בינתיים.', '— for now.', false),
  ('journeyHub.locked.lede', 'journey-hub', 'locked', 'מגיע לכם ליווי שנבנה במיוחד עבורכם — תרגולים, אבחון, שיחות, ומשימות חודשיות מהמומחים שלנו. הכל כלול במנוי שבועי אחד.', 'You deserve coaching built around you — practices, assessment, conversations, and monthly tasks from our experts. All included in one weekly subscription.', false),
  ('journeyHub.locked.subLede', 'journey-hub', 'locked', 'אנחנו לא רוצים שתפספסו את זה.', 'We don''t want you to miss this.', false),
  ('journeyHub.preheader', 'journey-hub', 'preheader', 'מומחה מיאושי צמוד לכל זוג', 'A Mioshy expert paired with every couple', false),
  ('journeyHub.resumeHint', 'journey-hub', 'resumehint', 'יש לכם אבחון באמצע - המסלול ממתין להמשך.', 'You''ve got an assessment in progress — the path is waiting.', false),
  ('journeyHub.trust.0', 'journey-hub', 'trust', 'אבחון של 5 דקות', '5-minute assessment', false),
  ('journeyHub.trust.1', 'journey-hub', 'trust', 'מומחה צמוד', 'Personal expert', false),
  ('journeyHub.trust.2', 'journey-hub', 'trust', 'תוכנית אישית', 'Custom plan', false),
  ('journeyHub.trust.3', 'journey-hub', 'trust', 'ללא כרטיס אשראי', 'No credit card', false),
  ('journeyHub.why.badge', 'journey-hub', 'why', 'למה המסע הזה', 'Why this journey', false),
  ('journeyHub.why.items.0.h', 'journey-hub', 'why', 'מותאם לכם', 'Built around you', false),
  ('journeyHub.why.items.0.p', 'journey-hub', 'why', 'אבחון קצר ממפה את הזוגיות שלכם לפי 7 צירים. על בסיס התוצאות, המערכת בונה עבורכם מסלול שמתחיל בדיוק במקום שצריך.', 'A short assessment maps your relationship across 7 dimensions. Your roadmap starts exactly where it needs to - not where a generic course says to start.', false),
  ('journeyHub.why.items.1.h', 'journey-hub', 'why', 'קצב אנושי', 'Human pace', false),
  ('journeyHub.why.items.1.p', 'journey-hub', 'why', 'תוכן לא מוצף. בכל שבוע נפתח פרק חדש - תרגול, אתגר או שיחה לשני בני הזוג. מספיק זמן להרגיש ולחזור.', 'No content dumps. A new chapter opens each week - a practice, a challenge, or a shared conversation. Enough room to feel it, try it, come back to it.', false),
  ('journeyHub.why.items.2.h', 'journey-hub', 'why', 'תוכן מומחים', 'Written by experts', false),
  ('journeyHub.why.items.2.p', 'journey-hub', 'why', 'כל פריט נכתב יחד עם מטפלי זוגות. פרקטי, מבוסס מחקר, מיושם בחיים האמיתיים - לא ציטוטים מ-Instagram.', 'Every piece is co-written with couples therapists. Practical, research-based, actually doable - not Instagram quotes.', false),
  ('journeyHub.why.items.3.h', 'journey-hub', 'why', 'יחד באמת', 'Together, for real', false),
  ('journeyHub.why.items.3.p', 'journey-hub', 'why', 'שני בני הזוג רואים את אותו המסע. מסמנים שיחות, כותבים רפלקציות, ורואים איך התקדמתם - באמת יחד.', 'Both partners see the same journey. Mark conversations, write reflections, and watch how you grow - together, for real.', false),
  ('journeyHub.why.stats.0.label', 'journey-hub', 'why', 'אישי לכם', 'Personal', false),
  ('journeyHub.why.stats.1.label', 'journey-hub', 'why', '5 דקות', '5 minutes', false),
  ('journeyHub.why.stats.2.label', 'journey-hub', 'why', 'מבוסס מחקר', 'Research-based', false),
  ('journeyHub.why.stats.3.label', 'journey-hub', 'why', 'לזוג', 'For couples', false),
  ('journeyHub.why.title', 'journey-hub', 'why', 'לא עוד עצות כלליות. מסלול שנבנה סביבכם.', 'No more generic advice. A path built around you.', false),
  ('journeyTimeline.celebration.body', 'journey-timeline', 'celebration', 'רגעים קטנים כאלה הם מה שבונה קרבה שנשארת. המסע שלכם מתקדם - צעד אחר צעד, בקצב שלכם.', 'Small moments like this are what build a closeness that lasts. Your journey is moving forward - step by step, at your own pace.', false),
  ('journeyTimeline.celebration.continue', 'journey-timeline', 'celebration', 'המשך למסע', 'Continue your journey', false),
  ('journeyTimeline.celebration.credibilityProof', 'journey-timeline', 'celebration', 'שיטה שנבחנה עם מאות זוגות · למעלה מ-25 שנות ליווי', 'A method tested with hundreds of couples · Over 25 years of practice', false),
  ('journeyTimeline.celebration.credibilitySub', 'journey-timeline', 'celebration', 'מלווה זוגות משנת 2001', 'Coaching couples since 2001', false),
  ('journeyTimeline.celebration.credibilityTitle', 'journey-timeline', 'celebration', 'איציק ברלב', 'Itzik Berlav', false),
  ('journeyTimeline.celebration.impactLabel', 'journey-timeline', 'celebration', 'מה השגתם כרגע', 'What you just built', false),
  ('journeyTimeline.celebration.impactLine', 'journey-timeline', 'celebration', 'בניתם שריר חדש לזוגיות - הקשבה, נוכחות וכנות בין שניכם. זה לא נבנה מאליו.', 'You grew a new relationship muscle - listening, presence, honesty between the two of you. That doesn''t happen by accident.', false),
  ('journeyTimeline.celebration.kicker', 'journey-timeline', 'celebration', 'עוד צעד קטן · שינוי אמיתי', 'One more step · real change', false),
  ('journeyTimeline.celebration.stay', 'journey-timeline', 'celebration', 'השארו כאן', 'Stay here', false),
  ('journeyTimeline.celebration.title', 'journey-timeline', 'celebration', 'עשיתם משהו חשוב ביחד.', 'You just did something that matters.', false),
  ('journeyTimeline.feedback.ariaLabel', 'journey-timeline', 'feedback', 'משוב על הפריט', 'Feedback on this item', false),
  ('journeyTimeline.feedback.cancel', 'journey-timeline', 'feedback', 'ביטול', 'Cancel', false),
  ('journeyTimeline.feedback.change', 'journey-timeline', 'feedback', 'שינוי', 'Change', false),
  ('journeyTimeline.feedback.heading', 'journey-timeline', 'feedback', 'איך זה היה?', 'How was that?', false),
  ('journeyTimeline.feedback.helperText', 'journey-timeline', 'feedback', 'המשוב משנה את מה שתקבלו אחר כך.', 'Your feedback changes what comes next.', false),
  ('journeyTimeline.feedback.notePlaceholder', 'journey-timeline', 'feedback', 'אופציונלי. מה לא עבד? המומחה/ת יקרא/תקרא.', 'Optional. What didn''t work? Your coach will read it.', false),
  ('journeyTimeline.feedback.postSubmitNote', 'journey-timeline', 'feedback', 'סימנתם "{label}". המסלול הבא מתחשב בזה.', 'You marked it "{label}". What''s next takes that in.', false),
