-- 091_cms_texts_backfill_all_missing.sql
--
-- Backfill ALL CMS keys used in the codebase but not yet seeded in
-- cms_texts. Without this, the affected strings render correctly on
-- the public site (via next-intl fallback to messages/he|en.json)
-- but do NOT appear in /admin/content for editing — Itzik discovered
-- this 2026-05-21 trying to find 'הזוגות שלנו משתפים' in the CRM.
--
-- 090 covered the Reviews section (27 keys). This migration sweeps
-- everything else: 662 keys across 17 page-namespaces. Values are
-- sourced from messages/{he,en}.json — same content the public site
-- currently renders via fallback. After this runs, every CmsText/
-- useCmsText call has a row to edit in /admin/content.
--
-- is_rich is auto-detected: any key whose he or en value contains
-- an HTML tag (<p>, <strong>, <em>, <br>, etc.) is marked is_rich=true
-- so the editor renders the rich-text toolbar. Pure-text values get
-- is_rich=false. This matches the convention in 085-090.
--
-- ON CONFLICT (key) DO NOTHING — safe to re-run; never clobbers an
-- existing admin edit. Same pattern as 085-090.

BEGIN;

ON CONFLICT (key) DO NOTHING;

COMMIT;
